const S = v => (v==null?'':String(v)).trim();
const vid = u => { const m=String(u||'').match(/shorts\/([\w-]{11})|v=([\w-]{11})|youtu\.be\/([\w-]{11})|\/([\w-]{11})(?:\?|$)/); return m?(m[1]||m[2]||m[3]||m[4]):''; };
const rows = $('Load creator data').all().map(i=>i.json);
let dl = $('Apify · Download media').all().map(i=>i.json);
if (dl.length===1 && Array.isArray(dl[0])) dl = dl[0];
const map = {};
for (const d of dl) {
  const id = S(d.id) || vid(d.input) || vid(d.downloadedFileUrl);
  if (!id) continue;
  map[id] = {
    audio_url: S(d.downloadedFileUrl) || S(d.audioOnlyUrl) || '',
    video_url: S(d.downloadedFileUrl) || S(d.videoOnlyUrl) || '',
  };
}
return rows.map(r => {
  const m = map[S(r.id)] || {};
  return { json: { ...r, audio_url: m.audio_url || '', video_url: m.video_url || '' } };
});

const row = { ...$('Enrich rows').item.json };
row._transcript = String(($('Wizper · video (speech)').item.json.text)||'').trim() || null;
const out = String(($json && $json.output)||'');
const g = (lab)=>{const m=out.match(new RegExp(lab+':([\\s\\S]*?)(?=SCENE:|TEXT:|$)','i'));return m?m[1].trim():'';};
row._visual_desc = g('SCENE') || null;
row._overlay = g('TEXT') || null;
return { json: row };

