const S=v=>(v==null?'':String(v)).trim();
const N=v=>{const n=parseInt(String(v).replace(/[, ]/g,''),10);return isNaN(n)?0:n;};
const rows=$input.all().map(i=>i.json);
const corpus=[],visual=[],audience=[];
for(const r of rows){
  const id=S(r.id)||('row_'+Math.random().toString(36).slice(2,10));
  const mtype=S(r.media_type).toLowerCase();
  const author=(S(r.author)||'creator').toLowerCase();
  if(mtype==='comment'&&author==='audience'){audience.push({id,platform:S(r.platform),text:S(r.caption)||S(r._transcript)||S(r.transcript),likes:N(r.likes)});continue;}
  if(r._visual_desc)visual.push({id,platform:S(r.platform),media_type:mtype,visual_desc:S(r._visual_desc)});
  let caption=S(r.caption)||null; if(r._overlay)caption=(caption?caption+' ':'')+S(r._overlay);
  const transcript=S(r._transcript)||S(r.transcript)||null; const title=S(r.title)||null;
  if(!(transcript||caption||title))continue;
  const hook=S(r.hook)||(transcript||caption||'').replace(/\n/g,' ').split('. ')[0].split(' ').slice(0,14).join(' ');
  corpus.push({id,platform:S(r.platform),media_type:mtype,title,transcript,caption,hook,published_at:S(r.published_at)||null,metrics:{views:N(r.views),likes:N(r.likes),comments:N(r.comments)},performance_percentile:0});
}
const sc=corpus.map(i=>(i.metrics.likes+i.metrics.comments)/Math.max(i.metrics.views,1));
const sorted=[...sc].sort((a,b)=>a-b);
corpus.forEach((it,k)=>{const rank=sorted.filter(v=>v<=sc[k]).length; it.performance_percentile=corpus.length?Math.round((rank/corpus.length)*1000)/1000:0;});
const c0=rows[0]||{};
const corpusDoc={creator:{handle:S(c0.creator||c0.handle),niche:S(c0.niche),platforms:[...new Set(corpus.map(i=>i.platform).filter(Boolean))]},items:corpus};
return [
  {json:{fileName:'corpus.json',fileContent:JSON.stringify(corpusDoc,null,2),corpus:corpusDoc}},
  {json:{fileName:'visual_profile.json',fileContent:JSON.stringify({items:visual},null,2)}},
  {json:{fileName:'audience_signals.json',fileContent:JSON.stringify({items:audience},null,2)}},
];

const a = $('Assemble buckets + percentile').first().json;
const doc = a.corpus || JSON.parse(a.fileContent||'{"items":[]}');
const items = doc.items || [];
const lines = items.map(i=>`- [pct ${i.performance_percentile}] TITLE: ${i.title}\n  SPEECH: ${i.transcript||'(none)'}\n  CAPTION: ${i.caption||'(none)'}`).join('\n');
const fpInput = `CREATOR: ${doc.creator&&doc.creator.handle} | NICHE: ${doc.creator&&doc.creator.niche}\nItems (weight high-percentile most):\n${lines}`;
return [{ json: { fingerprint_input: fpInput, items_total: items.length, items_with_transcript: items.filter(i=>i.transcript).length } }];
